export const LAND_PATH = LAND_PARTS.join("");

/** Where a point lands on the map, in its units. */
export function project(latitude: number, longitude: number): [number, number] {
  return [
    ((longitude + 180) / 360) * WORLD.width,
    ((WORLD.topLatitude - latitude) /
      (WORLD.topLatitude - WORLD.bottomLatitude)) *
      WORLD.height,
  ];
}
